static MOD_UNUSED int box_current_is(const char* menu) {
    const char* id = API->boxMenu != 0 ? API->boxMenu->Current(SELF) : 0;
    return id != 0 && strcmp(id, menu) == 0;
}

static MOD_UNUSED int box_overlay_is(const char* menu) {
    const char* id = API->boxMenu != 0 ? API->boxMenu->Box(SELF) : 0;
    return id != 0 && strcmp(id, menu) == 0;
}

/* An overlay is shown when Box() answers with a non-empty id */
static MOD_UNUSED int box_overlay_any(void) {
    const char* id = API->boxMenu != 0 ? API->boxMenu->Box(SELF) : 0;
    return id != 0 && id[0] != 0;
}
